pub(crate) fn sketchfab_planaria_surface() -> TriangleMeshSurface {
    TriangleMeshSurface::new(
        PLANARIA_SKETCHFAB_SURFACE_ID,
        PLANARIA_SKETCHFAB_POSITIONS
            .iter()
            .map(|position| Vec3::new(position[0], position[1], position[2]))
            .collect(),
        PLANARIA_SKETCHFAB_TRIANGLES.to_vec(),
    )
}
